import type { Option } from "fp-ts/Option";
import type { ValidatedNEA } from "../Validated";
import { ValueNotExpected } from "../ValidationErrors";
/**
 * A validator that returns {@link Validated} containing
 * the tested value, if the value equals the test value.
 * If the value passed in is not the test value, then
 * {@link Invalid} will be returned with an error of
 * {@link ValueNotExpected}.
 *
 * @internal
 */
export declare const asValue: <U>(testValue: U) => (value: unknown) => ValidatedNEA<ValueNotExpected, U>;
/**
 * A validator that returns {@link Validated} containing
 * `none`, if the value passed in is `undefined`,
 * `null` or `none`.
 * Otherwise, returns the result of the value passed
 * to {@link asValue} wrapped in `Some`.
 *
 * @internal
 */
export declare const asOptionalValue: <U>(testValue: U) => (value?: U | undefined) => ValidatedNEA<ValueNotExpected, Option<U>>;
